                }
                return 0;
            } else {
                fprintf(stderr, "error: --print-completions requires an argument\n");
                return 1;
            }
        } else if (strcmp(a, "--print-manpage") == 0) {
            printf("%% %s(1) genact manual\n", argv[0]);
